68	class SimulatorThreads
69	{
70	  public:
71	    SimulatorThreads() = delete;
72	    SimulatorThreads(const SimulatorThreads &) = delete;
73	    SimulatorThreads &operator=(SimulatorThreads &) = delete;
74	
75	    SimulatorThreads(uint32_t num_queues)
76	        : terminate(false),
77	          numQueues(num_queues),
78	          barrier(num_queues)
79	    {
80	        threads.reserve(num_queues);
81	    }
82	
83	    ~SimulatorThreads()
84	    {
85	        // This should only happen after exit has been
86	        // called. Subordinate event queues should normally (assuming
87	        // exit is called from Python) be waiting on the barrier when
88	        // this happens.
89	        //
90	        // N.B.: Not terminating here would make it impossible to
91	        // safely destroy the barrier.
92	        terminateThreads();
93	    }
94	
95	    void runUntilLocalExit()
96	    {
97	        assert(!terminate);
98	
99	        // Start subordinate threads if needed.
100	        if (threads.empty()) {
101	            // the main thread (the one running Python) handles queue 0,
102	            // so we only need to allocate new threads for queues 1..N-1.
103	            // We'll call these the "subordinate" threads.
104	            for (uint32_t i = 1; i < numQueues; i++) {
105	                threads.emplace_back(
106	                    [this](EventQueue *eq) {
107	                        thread_main(eq);
108	                    }, mainEventQueue[i]);
109	            }
110	        }
111	
112	        // This method is called from the main thread. All subordinate
113	        // threads should be waiting on the barrier when the function
114	        // is called. The arrival of the main thread here will satisfy
115	        // the barrier and start another iteration in the thread loop.
116	        barrier.wait();
117	    }
118	
119	    void
120	    terminateThreads()
121	    {
122	        assert(!terminate);
123	        if (threads.empty())
124	            return;
125	
126	        /* This function should only be called when the simulator is
127	         * handling a global exit event (typically from Python). This
128	         * means that the helper threads will be waiting on the
129	         * barrier. Tell the helper threads to exit and release them from
130	         * their barrier. */
131	        terminate = true;
132	        barrier.wait();
133	
134	        /* Wait for all of the threads to terminate */
135	        for (auto &t : threads) {
136	            t.join();
137	        }
138	
139	        terminate = false;
140	        threads.clear();
141	    }
142	
143	  protected:
144	    /**
145	     * The main function for all subordinate threads (i.e., all threads
146	     * other than the main thread).  These threads start by waiting on
147	     * threadBarrier.  Once all threads have arrived at threadBarrier,
148	     * they enter the simulation loop concurrently.  When they exit the
149	     * loop, they return to waiting on threadBarrier.  This process is
150	     * repeated until the simulation terminates.
151	     */
152	    void
153	    thread_main(EventQueue *queue)
154	    {
155	        /* Wait for all initialisation to complete */
156	        barrier.wait();
157	
158	        while (!terminate) {
159	            doSimLoop(queue);
160	            barrier.wait();
161	        }
162	    }
163	
164	    std::atomic<bool> terminate;
165	    uint32_t numQueues;
166	    std::vector<std::thread> threads;
167	    Barrier barrier;
168	};
