184	/** Simulate for num_cycles additional cycles.  If num_cycles is -1
185	 * (the default), we simulate to MAX_TICKS unless the max ticks has been set
186	 * via the 'set_max_tick' function prior. This function is exported to Python.
187	 * @return The SimLoopExitEvent that caused the loop to exit.
188	 */
189	GlobalSimLoopExitEvent *global_exit_event= nullptr;
190	GlobalSimLoopExitEvent *
191	simulate(Tick num_cycles)
192	{
193	    // install the sigint handler to catch ctrl-c and exit the sim loop cleanly
194	    // Note: This should be done before initializing the threads
195	    initSigInt();
196	    initSigCont();
197	
198	    if (global_exit_event)//cleaning last global exit event
199	        global_exit_event->clean();
200	    std::unique_ptr<GlobalSyncEvent, DescheduleDeleter> quantum_event;
201	
202	    DPRINTF(EnteringEventQueue, "Entering event queue @ %d. Starting "
203	        "simulation...\n", curTick());
204	
205	    if (!simulatorThreads)
206	        simulatorThreads.reset(new SimulatorThreads(numMainEventQueues));
207	
208	    if (!simulate_limit_event) {
209	        // If the simulate_limit_event is not set, we set it to MaxTick.
210	        set_max_tick(MaxTick);
211	    }
212	
213	    if (num_cycles != -1) {
214	        // If the user has specified an exit event after X cycles, do so here.
215	        // Note: This will override any prior set max_tick behaviour (such as
216	        // that above when it is set to MAxTick).
217	        const Tick max_tick = num_cycles < MaxTick - curTick() ?
218	                                    curTick() + num_cycles : MaxTick;
219	
220	        // This is kept to `set_max_tick` instead of `schedule_tick_exit` to
221	        // preserve backwards functionality. It may be better to deprecate this
222	        // behaviour at some point in favor of `schedule_tick_exit`.
223	        set_max_tick(max_tick);
224	    }
225	
226	    if (numMainEventQueues > 1) {
227	        fatal_if(simQuantum == 0,
228	                 "Quantum for multi-eventq simulation not specified");
229	
230	        quantum_event.reset(
231	            new GlobalSyncEvent(curTick() + simQuantum, simQuantum,
232	                                EventBase::Progress_Event_Pri, 0));
233	
234	        inParallelMode = true;
235	    }
236	
237	    simulatorThreads->runUntilLocalExit();
238	    Event *local_event = doSimLoop(mainEventQueue[0]);
239	    assert(local_event);
240	
241	    // Restore normal ctrl-c operation as soon as the event queue is done
242	    restoreSigInt();
243	
244	    inParallelMode = false;
245	
246	    // locate the global exit event and return it to Python
247	    BaseGlobalEvent *global_event = local_event->globalEvent();
248	    assert(global_event);
249	
250	    global_exit_event =
251	        dynamic_cast<GlobalSimLoopExitEvent *>(global_event);
252	    assert(global_exit_event);
253	
254	    return global_exit_event;
255	}
