257	void set_max_tick(Tick tick)
258	{
259	    if (!simulate_limit_event) {
260	        simulate_limit_event = new GlobalSimLoopExitEvent(
261	            mainEventQueue[0]->getCurTick(),
262	            "simulate() limit reached", 0);
263	    }
264	    simulate_limit_event->reschedule(tick);
265	}
