268	Tick get_max_tick()
269	{
270	    if (!simulate_limit_event) {
271	        /* If the GlobalSimLoopExitEvent has not been setup, the maximum tick
272	         * is `MaxTick` as declared in "src/base/types.hh".
273	         */
274	        return MaxTick;
275	    }
276	
277	    return simulate_limit_event->when();
278	}
