287	/**
288	 * The main per-thread simulation loop. This loop is executed by all
289	 * simulation threads (the main thread and the subordinate threads) in
290	 * parallel.
291	 */
292	Event *
293	doSimLoop(EventQueue *eventq)
294	{
295	    // set the per thread current eventq pointer
296	    curEventQueue(eventq);
297	    eventq->handleAsyncInsertions();
298	
299	    bool mainQueue = eventq == getEventQueue(0);
300	
301	    while (1) {
302	        // there should always be at least one event (the SimLoopExitEvent
303	        // we just scheduled) in the queue
304	        assert(!eventq->empty());
305	        assert(curTick() <= eventq->nextTick() &&
306	               "event scheduled in the past");
307	
308	        if (mainQueue && async_event) {
309	            async_event = false;
310	            // Take the event queue lock in case any of the service
311	            // routines want to schedule new events.
312	            std::lock_guard<EventQueue> lock(*eventq);
313	            if (async_statdump || async_statreset) {
314	                statistics::schedStatEvent(async_statdump, async_statreset);
315	                async_statdump = false;
316	                async_statreset = false;
317	            }
318	
319	            if (async_io) {
320	                async_io = false;
321	                pollQueue.service();
322	            }
323	
324	            if (async_exit) {
325	                async_exit = false;
326	                exitSimLoop("user interrupt received");
327	            }
328	
329	            if (async_exception) {
330	                async_exception = false;
331	                return NULL;
332	            }
333	            if (async_hypercall) {
334	                async_hypercall = false;
335	                processExternalSignal();
336	            }
337	        }
338	
339	        Event *exit_event = eventq->serviceOne();
340	        if (exit_event != NULL) {
341	            return exit_event;
342	        }
343	    }
344	
345	    // not reached... only exit is return on SimLoopExitEvent
346	}
