577	/**
578	 * Queue of events sorted in time order
579	 *
580	 * Events are scheduled (inserted into the event queue) using the
581	 * schedule() method. This method either inserts a <i>synchronous</i>
582	 * or <i>asynchronous</i> event.
583	 *
584	 * Synchronous events are scheduled using schedule() method with the
585	 * argument 'global' set to false (default). This should only be done
586	 * from a thread holding the event queue lock
587	 * (EventQueue::service_mutex). The lock is always held when an event
588	 * handler is called, it can therefore always insert events into its
589	 * own event queue unless it voluntarily releases the lock.
590	 *
591	 * Events can be scheduled across thread (and event queue borders) by
592	 * either scheduling asynchronous events or taking the target event
593	 * queue's lock. However, the lock should <i>never</i> be taken
594	 * directly since this is likely to cause deadlocks. Instead, code
595	 * that needs to schedule events in other event queues should
596	 * temporarily release its own queue and lock the new queue. This
597	 * prevents deadlocks since a single thread never owns more than one
598	 * event queue lock. This functionality is provided by the
599	 * ScopedMigration helper class. Note that temporarily migrating
600	 * between event queues can make the simulation non-deterministic, it
601	 * should therefore be limited to cases where that can be tolerated
602	 * (e.g., handling asynchronous IO or fast-forwarding in KVM).
603	 *
604	 * Asynchronous events can also be scheduled using the normal
605	 * schedule() method with the 'global' parameter set to true. Unlike
606	 * the previous queue migration strategy, this strategy is fully
607	 * deterministic. This causes the event to be inserted in a separate
608	 * queue of asynchronous events (async_queue), which is merged main
609	 * event queue at the end of each simulation quantum (by calling the
610	 * handleAsyncInsertions() method). Note that this implies that such
611	 * events must happen at least one simulation quantum into the future,
612	 * otherwise they risk being scheduled in the past by
613	 * handleAsyncInsertions().
614	 */
615	class EventQueue
616	{
617	  private:
618	    friend void curEventQueue(EventQueue *);
619	
620	    std::string objName;
621	    Event *head;
622	    Tick _curTick;
623	
624	    //! Mutex to protect async queue.
625	    UncontendedMutex async_queue_mutex;
626	
627	    //! List of events added by other threads to this event queue.
628	    std::list<Event*> async_queue;
629	
630	    /**
631	     * Lock protecting event handling.
632	     *
633	     * This lock is always taken when servicing events. It is assumed
634	     * that the thread scheduling new events (not asynchronous events
635	     * though) have taken this lock. This is normally done by
636	     * serviceOne() since new events are typically scheduled as a
637	     * response to an earlier event.
638	     *
639	     * This lock is intended to be used to temporarily steal an event
640	     * queue to support inter-thread communication when some
641	     * deterministic timing can be sacrificed for speed. For example,
642	     * the KVM CPU can use this support to access devices running in a
643	     * different thread.
644	     *
645	     * @see EventQueue::ScopedMigration.
646	     * @see EventQueue::ScopedRelease
647	     * @see EventQueue::lock()
648	     * @see EventQueue::unlock()
649	     */
650	    UncontendedMutex service_mutex;
651	
652	    //! Insert / remove event from the queue. Should only be called
653	    //! by thread operating this queue.
654	    void insert(Event *event);
655	    void remove(Event *event);
656	
657	    //! Function for adding events to the async queue. The added events
658	    //! are added to main event queue later. Threads, other than the
659	    //! owning thread, should call this function instead of insert().
660	    void asyncInsert(Event *event);
661	
662	    EventQueue(const EventQueue &);
