144	            memcpy(e.data, cur_data, size);
145	            e.size = size; e.vaddr = vaddr; e.valid = true;
146	            hist_next = (hist_next + 1) % HIST_CAP;
147	        }
148	        if (probability <= 0.0f || source_fault_enum == SourceFault::None)
149	            return cur_data;
150	        Cycles cur = cpu->curCycle();
151	        if (cur < first_clock) return cur_data;
152	        if (last_clock != Cycles(0) && cur > last_clock) return cur_data;
153	        if (max_faults != 0 && faults_injected_count >= max_faults)
154	            return cur_data;
155	        // Bernoulli gate.
156	        std::uniform_real_distribution<float> dist(0.0f, 1.0f);
157	        if (dist(rng) >= probability) return cur_data;
158	
159	        // Find a STALE entry (valid, older than the just-recorded one). If
160	        // none yet, return cur_data (no residue possible).
161	        //  - FwdSourceSub/StaleLineReplay: pick the most-recent valid entry.
162	        //  - PhaseOffset (F6): pick the entry `phase_offset` steps back
163	        //    (modeling a timing-phase race — method3's no-op-ALU 100%->10-20%
164	        //    signature; a deeper history slot = a bigger phase misalignment).
165	        HistEntry *stale = nullptr;
166	        int start_depth = (source_fault_enum == SourceFault::PhaseOffset)
167	                          ? phase_offset : 0;
168	        for (int i = start_depth; i < HIST_CAP; ++i) {
169	            int idx = (hist_next - 1 - i + HIST_CAP) % HIST_CAP;
170	            if (hist[idx].valid && hist[idx].size >= size) {
171	                stale = &hist[idx];
172	                break;
173	            }
174	        }
175	        if (!stale) return cur_data;  // history too shallow — no substitution
176	
177	        // Copy the stale data into a stable buffer (the load's memData will
178	        // memcpy from this). Use a thread-local-ish static buffer.
179	        static thread_local uint8_t sub_buf[HIST_BYTES];
180	        memcpy(sub_buf, stale->data, size);
181	        stats->numFaultsInjected++;
182	        ++faults_injected_count;
183	        if (source_fault_enum == SourceFault::FwdSourceSub)
184	            stats->numFwdSourceSub++;
185	        else if (source_fault_enum == SourceFault::StaleLineReplay)
186	            stats->numStaleLineReplay++;
187	        else  // PhaseOffset
188	            stats->numPhaseOffset++;
189	        if (write_log) {
190	            *(log_stream->stream())
191	                << "Cycle: " << cpu->curCycle()
192	                << ", Site: store->load_forward_source"
193	                << ", SourceFault: " << sourceFaultToString(source_fault_enum)
194	                << ", Vaddr: 0x" << std::hex << vaddr
195	                << ", StaleVaddr: 0x" << stale->vaddr << std::dec
196	                << ", FwdSize: " << size
197	                << std::endl;
198	        }
199	        return sub_buf;
200	    }
