202	    void
203	    CHAOSLSQFwd::applyStructuralFault(uint8_t *data, unsigned size, Addr vaddr)
204	    {
205	        if (size == 0) return;
206	        switch (structural_fault_enum) {
207	            case StructuralFault::ByteLaneSkew: {
208	                int k = skew_bytes;
209	                if (k == 0) {
210	                    std::uniform_int_distribution<int> kd(1, 7);
211	                    k = kd(rng);
212	                }
213	                if (k < 1) k = 1;
214	                if (k >= (int)size) k = (int)size - 1;
215	                // Right-rotate the byte array by k (byte lane n gets data[(n+k)%size]).
216	                std::vector<uint8_t> tmp(data, data + size);
217	                for (unsigned n = 0; n < size; n++)
218	                    data[n] = tmp[(n + k) % size];
219	                stats->numStructuralByteLaneSkew++;
220	                break;
221	            }
222	            case StructuralFault::AllZero:
223	                std::memset(data, 0, size);
224	                stats->numStructuralAllZero++;
225	                break;
226	            case StructuralFault::None:
227	                break;
228	        }
229	        stats->numFaultsInjected++;
230	        ++faults_injected_count;
231	        if (write_log) {
232	            *(log_stream->stream())
233	                << "Cycle: " << cpu->curCycle()
234	                << ", CPU: " << cpu->name()
235	                << ", Site: store->load_forward"
236	                << ", StructuralFault: " << structuralFaultToString(structural_fault_enum)
237	                << ", Vaddr: 0x" << std::hex << vaddr << std::dec
238	                << ", FwdSize: " << size
239	                << std::endl;
240	        }
241	        DPRINTF(LSQUnit, "CHAOSLSQFwd: structural %s on forwarded data "
242	                "(vaddr=%#x size=%u)\n",
243	                structuralFaultToString(structural_fault_enum), vaddr, size);
244	    }
