246	    uint64_t
247	    CHAOSLSQFwd::generateRandomMask(int bits_to_change)
248	    {
249	        // D2: 64-bit mask (was 8-bit). For maskWidth=1 the caller truncates
250	        // to the low 8 bits (legacy single-byte behavior); for maskWidth>1
251	        // the mask spans the whole little-endian window.
252	        uint64_t mask = 0;
253	        // Bit positions span [0, mask_width*8 - 1] so the random flip can
254	        // land in any byte of the window (not just byte 0).
255	        int bit_span = mask_width * 8;
256	        if (bit_span > 64) bit_span = 64;  // paranoia
257	        std::uniform_int_distribution<int> bitDist(0, bit_span - 1);
258	        while (bits_to_change-- > 0) mask |= (1ULL << bitDist(rng));
259	        return mask;
260	    }
