262	    void
263	    CHAOSLSQFwd::writeLog(const char *type, unsigned size, Addr vaddr,
264	                          int byte_off, uint64_t mask, int width)
265	    {
266	        if (!write_log) return;
267	        *(log_stream->stream())
268	            << "Cycle: " << cpu->curCycle()
269	            << ", CPU: " << cpu->name()
270	            << ", Site: store->load_forward"
271	            << ", FaultType: " << type
272	            << ", Vaddr: 0x" << std::hex << vaddr << std::dec
273	            << ", FwdSize: " << size
274	            << ", ByteOffset: " << byte_off
275	            << ", MaskWidth: " << width
276	            << ", Mask: 0x" << std::hex << mask << std::dec
277	            << std::endl;
278	    }
