280	    void
281	    CHAOSLSQFwd::corrupt(uint8_t *data, unsigned size, Addr vaddr)
282	    {
283	        // Hot-path short-circuit: no injection configured.
284	        if (probability <= 0.0f) return;
285	        Cycles cur = cpu->curCycle();
286	        if (cur < first_clock) return;
287	        if (last_clock != Cycles(0) && cur > last_clock) return;
288	        if (max_faults != 0 && faults_injected_count >= max_faults) return;
289	
290	        // Bernoulli: does this forwarding event get corrupted?
291	        std::uniform_real_distribution<float> dist(0.0f, 1.0f);
292	        if (dist(rng) >= probability) return;
293	        if (size == 0) return;
294	
295	        // S1-5 (P-D1): structural (whole-word) faults take precedence over
296	        // the D2 per-byte bit-fault path when configured. They cannot be
297	        // expressed as a bit flip (verified bit-exact vs core 179 crashes),
298	        // so they are a separate axis.
299	        if (structural_fault_enum != StructuralFault::None) {
300	            applyStructuralFault(data, size, vaddr);
301	            return;
302	        }
303	
304	        // Choose byte to corrupt (low byte of the masked window).
305	        int off = byte_offset;
306	        if (off < 0) {
307	            std::uniform_int_distribution<int> bdist(0, (int)size - 1);
308	            off = bdist(rng);
309	        }
310	        if (off >= (int)size) off = (int)size - 1;
311	
312	        // D2: maskWidth consecutive bytes (little-endian) starting at `off`.
313	        // Clamp the window to the forwarded buffer so we never run off the
314	        // end. maskWidth=1 + mask low 8 bits == legacy single-byte behavior.
315	        int width = mask_width;
316	        if (width < 1) width = 1;
317	        if (width > 8) width = 8;
318	        if (off + width > (int)size) width = (int)size - off;
319	        if (width < 1) width = 1;  // paranoia
320	
321	        uint64_t mask = fault_mask.any()
322	            ? fault_mask.to_ullong()
323	            : generateRandomMask(num_bits_to_change);
324	        // Truncate the mask to the active window width.
325	        uint64_t width_mask = (width >= 8) ? mask : (mask & ((1ULL << (8*width)) - 1));
326	
327	        FaultType chosen = fault_type_enum;
328	        if (fault_type_enum == FaultType::Random) {
329	            int idx = random_fault_distribution(rng);
330	            chosen = static_cast<FaultType>(idx);
331	        }
332	
333	        // Read the window as a little-endian uint64, apply the mask, write
334	        // back only the active bytes (same RMW pattern as CHAOSPhysReg vec).
335	        uint64_t win_val = 0;
336	        for (int b = 0; b < width; ++b)
337	            win_val |= ((uint64_t)data[off + b]) << (8 * b);
338	
339	        switch (chosen) {
340	            case FaultType::StuckAtZero:
341	                win_val &= ~width_mask;
342	                stats->numStuckAtZero++;
343	                break;
344	            case FaultType::StuckAtOne:
345	                win_val |= width_mask;
346	                stats->numStuckAtOne++;
347	                break;
348	            case FaultType::BitFlip:
349	                win_val ^= width_mask;
350	                stats->numBitFlips++;
351	                break;
352	            default: break;
353	        }
354	
355	        for (int b = 0; b < width; ++b)
356	            data[off + b] = (uint8_t)((win_val >> (8 * b)) & 0xff);
357	
358	        stats->numFaultsInjected++;
359	        ++faults_injected_count;
360	        writeLog(faultTypeToString(chosen), size, vaddr, off, width_mask, width);
361	        DPRINTF(LSQUnit, "CHAOSLSQFwd: corrupted forwarded bytes [%d+%d) "
362	                "(vaddr=%#x mask=%#llx type=%s)\n", off, width, vaddr,
363	                (unsigned long long)width_mask, faultTypeToString(chosen));
364	    }
