21	    CHAOSPhysReg::CHAOSPhysReg(const CHAOSPhysRegParams &p)
22	        : SimObject(p),
23	          cpu(dynamic_cast<o3::CPU *>(p.cpu)),
24	          fi_mode(stringToMode(p.injectionMode)),
25	          target_phys_idx(p.targetPhysRegIdx),
26	          target_arch_idx(p.targetArchRegIdx),
27	          reg_target_class(stringToRegClassSel(p.regTargetClass)),
28	          vec_lane_width(p.vecLaneWidth),
29	          vec_lane_offset(p.vecLaneOffset),
30	          probability(p.probability),
31	          num_bits_to_change(p.bitsToChange),
32	          fault_type_enum(stringToFaultType(p.faultType)),
33	          fault_mask(std::bitset<64>(p.faultMask)),
34	          bit_flip_prob(0.9),
35	          stuck_at_zero_prob(0.05),
36	          stuck_at_one_prob(0.05),
37	          trigger_value_mask(p.triggerValueMask),
38	          trigger_value_pattern(p.triggerValuePattern),
39	          semantic_role(p.semanticRole),
40	          first_clock(Cycles(p.firstClock)),
41	          last_clock(Cycles(p.lastClock)),
42	          max_faults(p.maxFaults),
43	          faults_injected_count(0),
44	          rng_seed(p.rngSeed),
45	          write_log(p.writeLog),
46	          attackEvent([this] { this->attackCheck(); }, name()),
47	          periodicCheck([this] { this->checkPermanent(); }, name() + ".periodicCheck"),
48	          readTraceEvent([this] { this->readTraceCheck(); }, name() + ".readTrace"),
49	          stats(nullptr)
50	    {
51	        if (!cpu) {
52	            throw std::runtime_error(
53	                "CHAOSPhysReg: cpu is not an O3CPU. CHAOSPhysReg only supports "
54	                "O3CPU (it needs regFile/renameMap). Cast failed.");
55	        }
56	        if (probability > 0.0) {
57	            log_stream = simout.create("fault_injections.log", false, true);
58	            if (!log_stream || !log_stream->stream()) {
59	                panic("CHAOSPhysReg: Could not open log file");
60	            }
61	            stats = std::make_unique<CHAOSPhysRegStats>(this);
62	            rng.seed(rng_seed != 0 ? rng_seed : rd());
63	            if (num_bits_to_change == -1) {
64	                std::uniform_int_distribution<int> dist(1, 64);
65	                num_bits_to_change = dist(rng);
66	            }
67	            inter_fault_cycles_dist = std::geometric_distribution<unsigned>(probability);
68	            unsigned next_fault_cycle_distance = inter_fault_cycles_dist(rng);
69	            scheduleAttackEvent(first_clock + Cycles(next_fault_cycle_distance));
70	            scheduleCheckPermanentFault(first_clock + Cycles(1));
71	        }
72	    }
