149	    uint64_t
150	    CHAOSPhysReg::generateRandomMask(std::mt19937 &gen, int bits_to_change, int len)
151	    {
152	        uint64_t mask = 0;
153	        std::uniform_int_distribution<int> bitDist(0, len - 1);
154	        while (bits_to_change-- > 0) mask |= (1ULL << bitDist(gen));
155	        return mask;
156	    }
