158	    // Core: resolve a target PHYSICAL register id according to the fi_mode,
159	    // then read-modify-write it directly in the physical register file.
160	    // This is the key difference from CHAOSReg (which wrote the commitRenameMap
161	    // phys reg via ThreadContext::setReg — a backdoor that doesn't propagate
162	    // to in-flight instructions on O3).
163	    void
164	    CHAOSPhysReg::processFault(ThreadID tid)
165	    {
166	        // 1. Resolve target register class (integer / floating_point / vector).
167	        // 'both' picks one at random per injection across the three classes (a
168	        // real cell doesn't know its class either; this mirrors the ITC'23/GeFIN
169	        // phys abstraction).
170	        gem5::RegClassType target_class = gem5::IntRegClass;
171	        if (reg_target_class == RegClassSel::FloatingPoint) {
172	            target_class = gem5::FloatRegClass;
173	        } else if (reg_target_class == RegClassSel::Vector) {
174	            target_class = gem5::VecRegClass;
175	        } else if (reg_target_class == RegClassSel::Both) {
176	            switch (std::uniform_int_distribution<>(0, 2)(rng)) {
177	              case 0: target_class = gem5::IntRegClass; break;
178	              case 1: target_class = gem5::FloatRegClass; break;
179	              default: target_class = gem5::VecRegClass; break;
180	            }
181	        }
182	
183	        // 2. Resolve target physical register id.
184	        PhysRegIdPtr phys_reg = nullptr;
185	        int chosen_phys_idx = -1;     // for logging
186	        int chosen_arch_idx = -1;     // for logging (arch modes)
187	
188	        if (fi_mode == Mode::Phys) {
189	            // Inject by physical register index. A real defective cell has no
190	            // notion of architectural registers; whoever is allocated to this
191	            // slot gets hit. This is the ITC'23/GeFIN abstraction.
192	            int n;
193	            if (target_class == gem5::FloatRegClass)
194	                n = (int)cpu->physRegFile().numFloatPhysRegs();
195	            else if (target_class == gem5::VecRegClass)
196	                n = (int)cpu->physRegFile().numVecPhysRegs();
197	            else
198	                n = (int)cpu->physRegFile().numIntPhysRegs();
199	            if (n <= 0) return;
200	            chosen_phys_idx = (target_phys_idx >= 0)
201	                ? target_phys_idx
202	                : std::uniform_int_distribution<>(0, n - 1)(rng);
203	            if (chosen_phys_idx >= n) return;
204	            if (target_class == gem5::FloatRegClass)
205	                phys_reg = cpu->physRegFile().floatPhysRegId(chosen_phys_idx);
206	            else if (target_class == gem5::VecRegClass)
207	                phys_reg = cpu->physRegFile().vecPhysRegId(chosen_phys_idx);
208	            else
209	                phys_reg = cpu->physRegFile().intPhysRegId(chosen_phys_idx);
210	
211	            // Liveness probe: is this physical slot currently FREE (inactive)
212	            // or ALLOCATED (active)? Correct criterion per project notes: a phys
213	            // reg NOT in the free list is allocated — it may be held as a source
214	            // by in-flight renamed-but-unexecuted instructions even if no rename
215	            // map entry currently maps it (older version superseded but not yet
216	            // released). So "not free" = active = may be read. (The earlier
217	            // "rename map reverse-walk" criterion was too narrow and mislabeled
218	            // some live slots as dead, producing the dead-slot SDC anomaly.)
219	            bool is_free = cpu->physFreeList().isFree(target_class, phys_reg);
220	            free_list_size_at_inject = cpu->physFreeList().numFreeRegs(
221	                target_class);
222	            if (!is_free) {
223	                // active — also record which arch reg (if any) maps to it now,
224	                // for diagnostics (walk rename map; best-effort, not the
225	                // liveness source of truth).
226	                gem5::ThreadContext *tc = cpu->getContext(tid);
227	                if (tc) {
228	                    gem5::BaseISA *isa = tc->getIsaPtr();
229	                    if (isa) {
230	                        const auto &rc = isa->regClasses();
231	                        const gem5::RegClass *ic = rc[target_class];
232	                        int na = ic ? ic->numRegs() : 0;
233	                        // X0-X30 (cap 31) for int; V0-V31 (cap 32) for
234	                        // float AND vector (AArch64 V/D/Q share the file).
235	                        int cap;
236	                        if (target_class == gem5::IntRegClass)
237	                            cap = (na < 31 ? na : 31);
238	                        else
239	                            cap = (na < 32 ? na : 32);
240	                        for (int a = 0; a < cap; a++) {
241	                            gem5::RegId ar(*ic, a);
242	                            const gem5::RegId flat = ar.flatten(*isa);
243	                            PhysRegIdPtr pm =
244	                                cpu->frontRenameMap()[tid].lookup(flat);
245	                            if (pm && pm->index() == chosen_phys_idx) {
246	                                chosen_arch_idx = a;
247	                                break;
248	                            }
249	                        }
250	                    }
251	                }
252	            } else {
253	                chosen_arch_idx = -2;  // sentinel: free/inactive
254	            }
255	        } else {
256	            // arch_frontend: renameMap.lookup      (in-flight mapping)
257	            // arch_commit:   commitRenameMap.lookup (committed mapping = CHAOSReg)
258	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
259	            if (!thread_context) return;
260	            gem5::BaseISA *isa = thread_context->getIsaPtr();
261	            if (!isa) return;
262	            const auto &reg_classes = isa->regClasses();
263	            const gem5::RegClass *reg_class = reg_classes[target_class];
264	            if (!reg_class || reg_class->numRegs() == 0) return;
265	            int arch_idx = target_arch_idx;
266	            if (arch_idx < 0 || arch_idx >= reg_class->numRegs()) return;
267	            chosen_arch_idx = arch_idx;
268	            gem5::RegId arch_reg(*reg_class, arch_idx);
269	            // flatten to match the per-class rename map's indexing
270	            const gem5::RegId flat = arch_reg.flatten(*isa);
271	            if (fi_mode == Mode::ArchFrontend)
272	                phys_reg = cpu->frontRenameMap()[tid].lookup(flat);
273	            else // ArchCommit
274	                phys_reg = cpu->commitRenameMapAccess()[tid].lookup(flat);
275	            if (!phys_reg) return;
276	            chosen_phys_idx = phys_reg->index();
277	        }
278	
279	        if (!phys_reg) return;
280

280	
281	        // 3. Read current physical reg value, apply fault, write back.
282	        // VecRegClass holds a whole vector in a buffer (not a scalar RegVal),
283	        // so it goes through the getReg/setReg void*-overload; the fault mask
284	        // is applied to the first 8 bytes (one 64-bit word — enough to corrupt
285	        // the low lane of a NEON/SVE vector and propagate as SDC). int/float/
286	        // vecelem stay on the scalar RegVal path.
287	        FaultType chosen = fault_type_enum;
288	        if (fault_type_enum == FaultType::Random) {
289	            int idx = random_fault_distribution(rng);
290	            chosen = static_cast<FaultType>(idx);
291	        }
292	
293	        uint64_t mask = fault_mask.any()
294	            ? fault_mask.to_ullong()
295	            : generateRandomMask(rng, num_bits_to_change, 64);
296	
297	        if (target_class == gem5::VecRegClass) {
298	            // Buffer path: read the WHOLE vector, corrupt ONE lane, write back.
299	            // The buffer MUST be sized to the actual vector phys reg byte width
300	            // (AArch64 VecRegClass = up to 256B for SVE-2048b). The old fixed
301	            // `uint8_t buf[64]` overflowed by 192B on getReg (report issue #3).
302	            // Phase 2 item 1: NEON lane stratification — the fault is applied
303	            // to ONE lane of vec_lane_width bits at lane vec_lane_offset,
304	            // instead of always the low 64-bit word. So a per-lane SDC study
305	            // (plan §7.4 BM-NEON: 4x32/2x64/8x16 lanes) is possible.
306	            size_t vbytes = cpu->physRegFile().vecRegBytes();
307	            if (vbytes < sizeof(uint64_t)) vbytes = sizeof(uint64_t);  // paranoia
308	            std::vector<uint8_t> buf(vbytes, 0);
309	            cpu->physRegFile().getReg(phys_reg, buf.data());
310	            // Resolve the lane: width in bits -> bytes; clamp to vector width.
311	            int lw = vec_lane_width;
312	            if (lw != 8 && lw != 16 && lw != 32 && lw != 64) lw = 32;  // default
313	            int lane_bytes = lw / 8;
314	            int max_lanes = (int)(vbytes / lane_bytes);
315	            if (max_lanes < 1) max_lanes = 1;
316	            int lane = vec_lane_offset;
317	            if (lane < 0 || lane >= max_lanes)
318	                lane = std::uniform_int_distribution<>(0, max_lanes - 1)(rng);
319	            // The fault mask applies within the lane's bit window. Treat the
320	            // lane as a lane_bytes-wide little-endian integer; apply the
321	            // 64-bit mask truncated/padded to lane_bytes, then read-modify-write
322	            // only those bytes. (mask was generated for the scalar path as a
323	            // 64-bit value; for a 32-bit lane we use the low 32 bits, etc.)
324	            uint8_t *lane_ptr = buf.data() + (size_t)lane * lane_bytes;
325	            uint64_t lane_val = 0;
326	            for (int b = 0; b < lane_bytes; ++b)
327	                lane_val |= ((uint64_t)lane_ptr[b]) << (8 * b);
328	            uint64_t lane_mask = (lw < 64) ? (mask & ((1ULL << lw) - 1)) : mask;
329	            switch (chosen) {
330	              case FaultType::StuckAtZero:
331	                lane_val &= ~lane_mask;
332	                stats->numStuckAtZero++;
333	                stats->numPermanentFaults++;
334	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
335	                break;
336	              case FaultType::StuckAtOne:
337	                lane_val |= lane_mask;
338	                stats->numStuckAtOne++;
339	                stats->numPermanentFaults++;
340	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
341	                break;
342	              case FaultType::BitFlip:
343	                lane_val ^= lane_mask;
344	                stats->numBitFlips++;
345	                break;
346	              default: break;
347	            }
348	            for (int b = 0; b < lane_bytes; ++b)
349	                lane_ptr[b] = (uint8_t)((lane_val >> (8 * b)) & 0xff);
350	            cpu->physRegFile().setReg(phys_reg, buf.data());
351	            // log the lane for the evidence trail
352	            if (write_log) {
353	                *(log_stream->stream())
354	                    << "  [vec lane " << lane << "/" << max_lanes
355	                    << " width=" << lw << "bits mask=0x" << std::hex
356	                    << lane_mask << std::dec << "]" << std::endl;
357	            }
358	        } else {
359	            // Scalar path (int / float / vecelem).
360	            gem5::RegVal reg_val = cpu->physRegFile().getReg(phys_reg);
361	            // F3: data-dependent trigger (method2 under-voltage setup-time
362	            // violation). When trigger_value_mask != 0, inject ONLY if the
363	            // target's current value matches (val & mask) == pattern. This
364	            // models a defect that manifests on a specific bit pattern (e.g.
365	            // method2's x10 garbage pointer appeared only under -30mV VDDAVS
366	            // on specific __per_cpu_offset values). No match -> skip this
367	            // injection attempt entirely (no count, no log).
368	            if (trigger_value_mask != 0 &&
369	                ((uint64_t)reg_val & trigger_value_mask) != trigger_value_pattern) {
370	                if (write_log) {
371	                    *(log_stream->stream())
372	                        << "Cycle: " << cpu->curCycle()
373	                        << ", PhysReg[" << chosen_phys_idx
374	                        << "] F3 trigger MISS: val=0x" << std::hex
375	                        << (uint64_t)reg_val << " mask=0x" << trigger_value_mask
376	                        << " pattern=0x" << trigger_value_pattern << std::dec
377	                        << " — injection skipped.\n";
378	                }
379	                return;  // F3: not triggered, do not inject or count
380	            }
381	            switch (chosen) {
382	              case FaultType::StuckAtZero:
383	                reg_val &= ~mask;
384	                stats->numStuckAtZero++;
385	                stats->numPermanentFaults++;
386	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
387	                // G2: arm the write-path stuck mask so the bit is forced on
388	                // EVERY subsequent write to this phys slot — the correct
389	                // permanent (cell-stuck) model. Survives program re-writes,
390	                // rename reuse, and spec/commit. Polarity 0 = stuck_at_zero.
391	                cpu->physRegFile().setStuckTarget(target_class, chosen_phys_idx,
392	                                                  (uint64_t)mask, 0);
393	                break;
394	              case FaultType::StuckAtOne:
395	                reg_val |= mask;
396	                stats->numStuckAtOne++;
397	                stats->numPermanentFaults++;
398	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
399	                // G2: write-path stuck mask, polarity 1 = stuck_at_one.
400	                cpu->physRegFile().setStuckTarget(target_class, chosen_phys_idx,
401	                                                  (uint64_t)mask, 1);
402	                break;
403	              case FaultType::BitFlip:
404	                reg_val ^= mask;
405	                stats->numBitFlips++;
406	                break;
407	              default: break;
408	            }
409	            cpu->physRegFile().setReg(phys_reg, reg_val);
410	        }
411	        stats->numFaultsInjected++;
412	        ++faults_injected_count;
413	
414	        // Start read-tracing this phys slot until workload end, to measure
415	        // whether the injected cell is actually read after injection.
416	        // (Closure check: SDC|read>0 should be similar for layer2 & layer3,
417	        //  SDC|read==0 should be ~0.) The readTraceEvent reschedules itself
418	        // every 1000 cycles until all threads halt, then writes the final
419	        // read count to the log.
420	        traced_phys_idx = chosen_phys_idx;
421	        reads_before_overwrite = 0;
422	        trace_overwritten = false;
423	        overwrite_recorded = false;
424	        overwritten_at_cycle = 0;
425	        cpu->physRegFile().setReadTraceTarget(target_class, chosen_phys_idx);
426	        if (!readTraceEvent.scheduled()) {
427	            schedule(readTraceEvent, cpu->clockEdge(Cycles(100000)));
428	        }
429	
430	        if (write_log) {
431	            *(log_stream->stream())
432	                << "Cycle: " << cpu->curCycle()
433	                << ", CPU: " << cpu->name()
434	                << ", Thread: " << tid
435	                << ", Mode: " << (fi_mode == Mode::Phys ? "phys"
436	                              : fi_mode == Mode::ArchFrontend ? "arch_frontend"
437	                              : "arch_commit")
438	                << ", RegClass: " << (target_class == gem5::FloatRegClass
439	                                       ? "fp"
440	                                       : (target_class == gem5::VecRegClass
441	                                          ? "vec" : "int"))
442	                << ", PhysReg[" << chosen_phys_idx << "]"
443	                << (fi_mode == Mode::Phys
444	                    ? (chosen_arch_idx == -2
445	                       ? " (Inactive/free slot)"
446	                       : (chosen_arch_idx >= 0
447	                          ? " (Active, mapped from ArchReg[" + std::to_string(chosen_arch_idx) + "])"
448	                          : " (Active, held by in-flight inst, no current rename-map entry)"))
449	                    : (chosen_arch_idx >= 0
450	                       ? " (<= ArchReg[" + std::to_string(chosen_arch_idx) + "])"
451	                       : ""))
452	                << ", FaultType: " << faultTypeToString(chosen)
453	                << ", Mask: " << std::bitset<64>(mask)
454	                << ", FreeListSize: " << free_list_size_at_inject
455	                << (!semantic_role.empty()
456	                    ? ", SemanticRole: " + semantic_role
457	                    : "");
458	            if (trigger_value_mask != 0) {
459	                *(log_stream->stream())
460	                    << ", F3trigger: mask=0x" << std::hex
461	                    << trigger_value_mask << " pattern=0x"
462	                    << trigger_value_pattern << std::dec;
463	            }
464	            *(log_stream->stream()) << std::endl;
465	        }
466	    }
