185	    /** Read-tracking hook for CHAOSPhysReg closure verification.
186	     *  Counts reads of the INJECTED VALUE (not the phys slot): once the
187	     *  target phys slot is WRITTEN (setReg), the injected value is gone, so
188	     *  counting stops. This fixes the earlier bug where free-list slots
189	     *  showed high read counts (the slot gets re-allocated and read many
190	     *  times, but those reads are of the NEW value, not the injected one).
191	     *  reads_before_overwrite = # times the injected value was read.
192	     *  overwritten = whether the slot was written (value destroyed).
193	     *  Tracking is type-aware (int and float phys spaces are independently
194	     *  numbered from 0), so both the RegClassType and idx must match.
195	     *  Hot-path: trace_type == InvalidRegClass when no injection in flight
196	     *  → short-circuit. */
197	    RegClassType trace_type = InvalidRegClass;  // class being tracked, or Invalid
198	    int trace_idx = -1;                          // phys idx within that class
199	    mutable uint64_t reads_before_overwrite = 0;  // reads of the injected value
200	    mutable bool trace_overwritten = false;      // set true when target slot is written
201	    void setReadTraceTarget(RegClassType type, int idx) {
202	        trace_type = type; trace_idx = idx;
203	        reads_before_overwrite = 0; trace_overwritten = false;
204	    }
205	    void clearReadTraceTarget() {
206	        trace_type = InvalidRegClass; trace_idx = -1;
207	    }
