211	    /** G2: stuck-at write-path mask (the CORRECT permanent-fault mechanism).
212	     *  A stuck cell must force its bit on EVERY write to the phys slot — not
213	     *  just once. The old CHAOSPhysReg::checkPermanent periodic re-apply did
214	     *  NOT propagate on O3 (it re-sticks at a polled instant, missing
215	     *  in-flight writes between polls; same root cause as the CHAOSReg
216	     *  commit-vs-frontend artifact). This hook lives in the write path so it
217	     *  survives program re-writes, rename reuse, and spec/commit ordering.
218	     *  Type-aware (int and float phys spaces are independently numbered),
219	     *  mirroring the read-trace pattern above. stuck_type == InvalidRegClass
220	     *  means no stuck fault in flight -> short-circuit. */
221	    RegClassType stuck_type = InvalidRegClass;
222	    int stuck_idx = -1;
223	    uint64_t stuck_mask = 0;
224	    uint8_t stuck_polarity = 0;    // 0 = stuck_at_zero (force 0), 1 = stuck_at_one
225	    void setStuckTarget(RegClassType type, int idx, uint64_t mask, uint8_t pol) {
226	        stuck_type = type; stuck_idx = idx; stuck_mask = mask; stuck_polarity = pol;
227	    }
