238	    RegVal
239	    getReg(PhysRegIdPtr phys_reg) const
240	    {
241	        const RegClassType type = phys_reg->classValue();
242	        const RegIndex idx = phys_reg->index();
243	
244	        RegVal val;
245	        switch (type) {
246	          case IntRegClass:
247	            val = intRegFile.reg(idx);
248	            // CHAOSPhysReg read-trace: count reads of the INJECTED VALUE.
249	            // Stop counting once the slot is written (injected value destroyed).
250	            // Hot-path: trace_type==Invalid when no trace → short-circuit.
251	            if (trace_type == IntRegClass && !trace_overwritten
252	                && (int)idx == trace_idx)
253	                ++reads_before_overwrite;
254	            DPRINTF(IEW, "RegFile: Access to int register %i, has data %#x\n",
255	                    idx, val);
256	            return val;
257	          case FloatRegClass:
258	            val = floatRegFile.reg(idx);
259	            // CHAOSPhysReg read-trace (float): symmetric to the int branch.
260	            if (trace_type == FloatRegClass && !trace_overwritten
261	                && (int)idx == trace_idx)
262	                ++reads_before_overwrite;
263	            DPRINTF(IEW, "RegFile: Access to float register %i has data %#x\n",
264	                    idx, val);
265	            return val;
266	          case VecElemClass:
267	            val = vectorElemRegFile.reg(idx);
268	            DPRINTF(IEW, "RegFile: Access to vector element register %i "
269	                    "has data %#x\n", idx, val);
270	            return val;
271	          case CCRegClass:
272	            val = ccRegFile.reg(idx);
273	            DPRINTF(IEW, "RegFile: Access to cc register %i has data %#x\n",
274	                    idx, val);
275	            return val;
276	          default:
277	            panic("Unsupported register class type %d.", type);
278	        }
279	    }
