281	    void
282	    getReg(PhysRegIdPtr phys_reg, void *val) const
283	    {
284	        const RegClassType type = phys_reg->classValue();
285	        const RegIndex idx = phys_reg->index();
286	
287	        switch (type) {
288	          case IntRegClass:
289	            *(RegVal *)val = getReg(phys_reg);
290	            break;
291	          case FloatRegClass:
292	            *(RegVal *)val = getReg(phys_reg);
293	            break;
294	          case VecRegClass:
295	            vectorRegFile.get(idx, val);
296	            // CHAOSPhysReg read-trace (vector): symmetric to int/float — count
297	            // reads of the injected VecReg cell until it is overwritten.
298	            if (trace_type == VecRegClass && !trace_overwritten
299	                && (int)idx == trace_idx)
300	                ++reads_before_overwrite;
301	            DPRINTF(IEW, "RegFile: Access to vector register %i, has "
302	                    "data %s\n", idx, vectorRegFile.regClass.valString(val));
303	            break;
304	          case VecElemClass:
305	            *(RegVal *)val = getReg(phys_reg);
306	            break;
307	          case VecPredRegClass:
308	            vecPredRegFile.get(idx, val);
309	            DPRINTF(IEW, "RegFile: Access to predicate register %i, has "
310	                    "data %s\n", idx, vecPredRegFile.regClass.valString(val));
311	            break;
312	          case MatRegClass:
313	            matRegFile.get(idx, val);
314	            DPRINTF(IEW, "RegFile: Access to matrix register %i, has "
315	                    "data %s\n", idx, matRegFile.regClass.valString(val));
316	            break;
317	          case CCRegClass:
318	            *(RegVal *)val = getReg(phys_reg);
319	            break;

320	          default:
321	            panic("Unrecognized register class type %d.", type);
322	        }
323	    }
