343	    void
344	    setReg(PhysRegIdPtr phys_reg, RegVal val)
345	    {
346	        const RegClassType type = phys_reg->classValue();
347	        const RegIndex idx = phys_reg->index();
348	
349	        switch (type) {
350	          case InvalidRegClass:
351	            break;
352	          case IntRegClass:
353	            // CHAOSPhysReg read-trace: a write to the traced slot destroys
354	            // the injected value → stop counting reads from this point.
355	            // (NOT the CHAOSPhysReg's own injection write — that goes through
356	            // a different path before setReadTraceTarget; the trace target is
357	            // set AFTER injection, so this write is a program/rename write.)
358	            if (trace_type == IntRegClass && (int)idx == trace_idx)
359	                trace_overwritten = true;
360	            // G2: stuck-at write-path mask. Force the stuck bits on EVERY
361	            // write to this phys slot (the correct permanent/cell-stuck
362	            // model — survives program re-writes, rename reuse, spec/commit).
363	            if (stuck_type == IntRegClass && (int)idx == stuck_idx) {
364	                if (stuck_polarity == 0) val &= ~stuck_mask;  // stuck_at_zero
365	                else                      val |=  stuck_mask;  // stuck_at_one
366	            }
367	            intRegFile.reg(idx) = val;
368	            DPRINTF(IEW, "RegFile: Setting int register %i to %#x\n",
369	                    idx, val);
370	            break;
371	          case FloatRegClass:
372	            // CHAOSPhysReg read-trace (float): symmetric overwrite detection.
373	            if (trace_type == FloatRegClass && (int)idx == trace_idx)
374	                trace_overwritten = true;
375	            // G2: stuck-at write-path mask (float), symmetric to int.
376	            if (stuck_type == FloatRegClass && (int)idx == stuck_idx) {
377	                if (stuck_polarity == 0) val &= ~stuck_mask;
378	                else                      val |=  stuck_mask;
379	            }
380	            floatRegFile.reg(idx) = val;
381	            DPRINTF(IEW, "RegFile: Setting float register %i to %#x\n",
382	                    idx, val);
383	            break;
384	          case VecElemClass:
385	            vectorElemRegFile.reg(idx) = val;
386	            DPRINTF(IEW, "RegFile: Setting vector element register %i to "
387	                    "%#x\n", idx, val);
388	            break;
389	          case CCRegClass:
390	            ccRegFile.reg(idx) = val;
391	            DPRINTF(IEW, "RegFile: Setting cc register %i to %#x\n",
392	                    idx, val);
393	            break;
394	          default:
395	            panic("Unsupported register class type %d.", type);
396	        }
397	    }
