399	    void
400	    setReg(PhysRegIdPtr phys_reg, const void *val)
401	    {
402	        const RegClassType type = phys_reg->classValue();
403	        const RegIndex idx = phys_reg->index();
404	
405	        switch (type) {
406	          case IntRegClass:
407	            setReg(phys_reg, *(RegVal *)val);
408	            break;
409	          case FloatRegClass:
410	            setReg(phys_reg, *(RegVal *)val);
411	            break;
412	          case VecRegClass:
413	            // CHAOSPhysReg read-trace (vector): a write to the traced cell
414	            // destroys the injected value → stop counting reads from here.
415	            if (trace_type == VecRegClass && (int)idx == trace_idx)
