            target_phys = cpu->physRegFile().intPhysRegId(phys_idx);
        else if (reg_target_class == RegClassSel::FloatingPoint)
            target_phys = cpu->physRegFile().floatPhysRegId(phys_idx);
        else
            target_phys = cpu->physRegFile().vecPhysRegId(phys_idx);
