void
CHAOSFreeList::writeLog(const std::string &type, ThreadID tid,
                        int phys_idx, int donor_arch,
                        const std::string &detail)
{
    if (!write_log) return;
    *(log_stream->stream())
        << "Cycle: " << cpu->curCycle()
        << ", CPU: " << cpu->name()
        << ", Thread: " << tid
        << ", Site: phys_free_list"
        << ", Mode: " << type
        << ", PhysReg: " << phys_idx
        << ", donor_arch: " << donor_arch
        << ", " << detail
        << (!semantic_role.empty() ? ", SemanticRole: " + semantic_role : "")
        << std::endl;
}

